package com.borisov.strelok;

public class Atm extends Activity implements View.OnClickListener {
    Button btn_Cancel;
    Button btn_OK;
    Button btn_std_weather;
    CheckBox convert_to_hPa_check;
    TextView label_altitude;
    TextView label_pressure;
    TextView label_temperature;
    Float local_Altitude;
    Float local_Pressure;
    Float local_Temperature;
    boolean m_convert_to_hPa;
    EditText textAltitude;
    EditText textPressure;
    EditText textTemperature;

    @Override // android.app.Activity
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.atm);
        getWindow().setSoftInputMode(3);
        this.textAltitude = (EditText) findViewById(R.id.EditAltitude);
        this.textTemperature = (EditText) findViewById(R.id.EditTemperature);
        this.textPressure = (EditText) findViewById(R.id.EditPressure);
        this.label_altitude = (TextView) findViewById(R.id.LabelAltitude);
        this.label_temperature = (TextView) findViewById(R.id.LabelTemperature);
        this.label_pressure = (TextView) findViewById(R.id.LabelPressure);
        this.convert_to_hPa_check = (CheckBox) findViewById(R.id.m_convert_to_hPa_switch);
        this.convert_to_hPa_check.setOnClickListener(this);
        this.convert_to_hPa_check.setChecked(Settings.m_convert_to_hPa.booleanValue());
        this.m_convert_to_hPa = Settings.m_convert_to_hPa.booleanValue();
        this.btn_OK = (Button) findViewById(R.id.ButtonOK);
        this.btn_OK.setOnClickListener(this);
        this.btn_Cancel = (Button) findViewById(R.id.ButtonCancel);
        this.btn_Cancel.setOnClickListener(this);
        this.btn_std_weather = (Button) findViewById(R.id.ButtonStandartAtm);
        this.btn_std_weather.setOnClickListener(this);
    }

    public void SetStandartPressureAndTemperature() {
        SaveFieldsToLocalVars();
        gEngine.atmosMetro(this.local_Altitude.floatValue() * 3.28084f);
        float temperature = (gEngine.m_std_temp - 32.0f) / 1.8f;
        float pressure = gEngine.m_std_press * 25.4f;
        if (Settings.m_convert_to_hPa.booleanValue()) {
            Float pressure_value = Float.valueOf(gEngine.Round(Converter.MMHG_TO_HPA(pressure).floatValue(), 0));
            this.textPressure.setText(pressure_value.toString());
        } else if (Settings.Metric_units_on.booleanValue()) {
            Float pressure_value2 = Float.valueOf(gEngine.Round(pressure, 0));
            this.textPressure.setText(pressure_value2.toString());
        } else {
            Float pressure_value3 = Float.valueOf(gEngine.Round(Converter.MMHG_TO_INHG(pressure).floatValue(), 2));
            this.textPressure.setText(pressure_value3.toString());
        }
        Float buffer = Float.valueOf(temperature);
        if (Settings.Metric_units_on.booleanValue()) {
            this.textTemperature.setText(Float.valueOf(gEngine.Round(buffer.floatValue(), 0)).toString());
        } else {
            Float buffer2 = Converter.C_TO_F(temperature);
            this.textTemperature.setText(Float.valueOf(gEngine.Round(buffer2.floatValue(), 0)).toString());
        }
    }

    public void ShowFields() {
        this.local_Altitude = gEngine.m_Altitude;
        this.local_Pressure = gEngine.m_Pressure;
        this.local_Temperature = gEngine.m_Temperature;
        ShowFieldsFromLocalVars();
    }

    public void ShowFieldsFromLocalVars() {
        if (Settings.m_convert_to_hPa.booleanValue()) {
            Float pressure_value = Float.valueOf(gEngine.Round(Converter.MMHG_TO_HPA(this.local_Pressure.floatValue()).floatValue(), 0));
            this.textPressure.setText(pressure_value.toString());
            this.label_pressure.setText(R.string.Pressure_label_hpa);
        } else if (Settings.Metric_units_on.booleanValue()) {
            Float pressure_value2 = Float.valueOf(gEngine.Round(this.local_Pressure.floatValue(), 0));
            this.textPressure.setText(pressure_value2.toString());
            this.label_pressure.setText(R.string.Pressure_label);
        } else {
            Float pressure_value3 = Float.valueOf(gEngine.Round(Converter.MMHG_TO_INHG(this.local_Pressure.floatValue()).floatValue(), 2));
            this.textPressure.setText(pressure_value3.toString());
            this.label_pressure.setText(R.string.Pressure_label_imp);
        }
        if (Settings.Metric_units_on.booleanValue()) {
            Float altitude = Float.valueOf(gEngine.Round(this.local_Altitude.floatValue(), 0));
            this.textAltitude.setText(altitude.toString());
            this.textTemperature.setText(this.local_Temperature.toString());
            this.label_altitude.setText(R.string.Altitude_label);
            this.label_temperature.setText(R.string.Temperature_label);
            return;
        }
        Float altitude2 = Float.valueOf(gEngine.Round(Converter.M_TO_F(this.local_Altitude.floatValue()).floatValue(), 0));
        this.textAltitude.setText(altitude2.toString());
        Float buffer = Converter.C_TO_F(this.local_Temperature.floatValue());
        this.textTemperature.setText(buffer.toString());
        this.label_altitude.setText(R.string.Altitude_label_imp);
        this.label_temperature.setText(R.string.Temperature_label_imp);
    }

    public void SaveFields() {
        SaveFieldsToLocalVars();
        gEngine.m_Pressure = this.local_Pressure;
        gEngine.m_Altitude = this.local_Altitude;
        gEngine.m_Temperature = this.local_Temperature;
    }

    public void SaveFieldsToLocalVars() {
        String pressure = this.textPressure.getText().toString();
        String altitude = this.textAltitude.getText().toString();
        String temperature = this.textTemperature.getText().toString();
        if (Settings.m_convert_to_hPa.booleanValue()) {
            if (pressure.length() != 0) {
                float pressure_value = Float.parseFloat(pressure);
                this.local_Pressure = Converter.HPA_TO_MMHG(pressure_value);
            }
        } else if (Settings.Metric_units_on.booleanValue()) {
            if (pressure.length() != 0) {
                this.local_Pressure = Float.valueOf(Float.parseFloat(pressure));
            }
        } else if (pressure.length() != 0) {
            float pressure_value2 = Float.parseFloat(pressure);
            this.local_Pressure = Converter.INHG_TO_MMHG(pressure_value2);
        }
        if (Settings.Metric_units_on.booleanValue()) {
            if (altitude.length() != 0) {
                this.local_Altitude = Float.valueOf(Float.parseFloat(altitude));
            }
            if (temperature.length() != 0) {
                this.local_Temperature = Float.valueOf(Float.parseFloat(temperature));
                return;
            }
            return;
        }
        if (altitude.length() != 0) {
            this.local_Altitude = Converter.F_TO_M(Float.parseFloat(altitude));
        }
        if (temperature.length() != 0) {
            this.local_Temperature = Converter.F_TO_C(Float.parseFloat(temperature));
        }
    }

    @Override // android.view.View.OnClickListener
    public void onClick(View src) {
        switch (src.getId()) {
            case R.id.m_convert_to_hPa_switch /* 2131165196 */:
                SaveFieldsToLocalVars();
                Settings.m_convert_to_hPa = Boolean.valueOf(this.convert_to_hPa_check.isChecked());
                ShowFieldsFromLocalVars();
                break;
            case R.id.ButtonStandartAtm /* 2131165197 */:
                SetStandartPressureAndTemperature();
                break;
            case R.id.ButtonOK /* 2131165198 */:
                SaveFields();
                finish();
                break;
            case R.id.ButtonCancel /* 2131165199 */:
                finish();
                break;
        }
    }

    @Override // android.app.Activity, android.view.KeyEvent.Callback
    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (keyCode != 4 || event.getRepeatCount() != 0) {
            return super.onKeyDown(keyCode, event);
        }
        SaveFields();
        finish();
        return true;
    }

    @Override // android.app.Activity
    protected void onPause() {
        SaveFields();
        super.onPause();
    }

    @Override // android.app.Activity
    protected void onResume() {
        super.onResume();
        ShowFields();
    }
}

