    public float Round(float e, int Precision) {
        float div = 1.0f;
        if (Precision >= 0) {
            while (true) {
                int Precision2 = Precision;
                Precision = Precision2 - 1;
                if (Precision2 <= 0) {
                    break;
                }
                div = (float) (div * 10.0d);
            }
        } else {
            while (true) {
                int Precision3 = Precision;
                Precision = Precision3 + 1;
                if (Precision3 >= 0) {
                    break;
                }
                div = (float) (div / 10.0d);
            }
        }
        return (float) (Math.floor((e * div) + 0.5d) / div);
    }

