    static float atmosMetro(float altitude) {
        float[] Alt = {0.0f, 1000.0f, 1500.0f, 2000.0f, 3000.0f, 4000.0f, 5000.0f, 6000.0f, 7000.0f, 8000.0f, 9000.0f, 10000.0f, 11000.0f, 12000.0f, 13000.0f, 14000.0f, 15000.0f};
        float[] Temp = {59.0f, 55.4f, 54.3f, 51.9f, 48.3f, 44.7f, 41.2f, 37.6f, 34.1f, 30.5f, 26.9f, 23.4f, 19.8f, 16.2f, 12.7f, 9.1f, 5.5f};
        float[] Press = {29.53f, 28.45f, 27.92f, 27.41f, 26.41f, 25.45f, 24.52f, 23.62f, 22.75f, 21.91f, 21.11f, 20.33f, 19.58f, 18.85f, 18.16f, 17.48f, 16.83f};
        float[] F_a = {1.0f, 1.031f, 1.0482f, 1.062f, 1.095f, 1.128f, 1.163f, 1.199f, 1.236f, 1.273f, 1.313f, 1.353f, 1.394f, 1.437f, 1.481f, 1.527f, 1.1573f};
        if (altitude > 15000.0f) {
            m_std_temp = Temp[16];
            m_SoundSpeed = 49.19d * Math.sqrt(m_std_temp + 459.67d);
            m_std_press = Press[16];
            return F_a[16];
        }
        if (altitude == 0.0f) {
            m_std_temp = Temp[0];
            m_SoundSpeed = 49.19d * Math.sqrt(m_std_temp + 459.67d);
            m_std_press = Press[0];
            return F_a[0];
        }
        int count = 0;
        while (altitude >= Alt[count]) {
            count++;
        }
        int upper_val = count - 1;
        int low_val = count;
        float S = (Temp[upper_val] - Temp[low_val]) / (Alt[low_val] - Alt[upper_val]);
        m_std_temp = Temp[upper_val] - ((altitude - Alt[upper_val]) * S);
        m_SoundSpeed = 49.19d * Math.sqrt(m_std_temp + 459.67d);
        float S2 = (Press[upper_val] - Press[low_val]) / (Alt[low_val] - Alt[upper_val]);
        m_std_press = Press[upper_val] - ((altitude - Alt[upper_val]) * S2);
        float S3 = (F_a[low_val] - F_a[upper_val]) / (Alt[low_val] - Alt[upper_val]);
        return F_a[upper_val] + ((altitude - Alt[upper_val]) * S3);
    }

package com.borisov.strelok;

    public static void Calc(boolean correct_zero_range) {
        SetVariables();
        SetZeroRange();
        if (correct_zero_range) {
            CalcCorrectedZeroRange();
        }
        float Target_Distance = m_Distance.floatValue();
        if (Target_Distance == 0.0f || muzzle_velocity_m == 0.0f) {
            Path_cm = 0.0f;
            m_dPathCm = m_ScopeHight;
            m_dPathMOA = Float.valueOf(0.0f);
            m_dPathTD = Float.valueOf(0.0f);
            m_PathClick = Float.valueOf(0.0f);
            Wind_cm = 0.0f;
            m_dWindCm = Float.valueOf(0.0f);
            m_dWindMOA = Float.valueOf(0.0f);
            m_dWindTD = Float.valueOf(0.0f);
            m_WindClick = Float.valueOf(0.0f);
            time_flight = 0.0d;
            Target_Drop = 0.0f;
            ret_vel = muzzle_velocity_m;
            ret_vel = Math.ceil(ret_vel);
            float tmp_speed = (float) (ret_vel * 3.280839895d);
            energy = (Math.pow(tmp_speed, 2.0d) * bullet_weight) / 450400.0d;
            energy = Math.ceil(energy * 1.357d);
        } else {
            if (muzzle_velocity_m > 600.0f) {
                KV = 900.0f;
                KP = 0.37f;
                CC = (float) (m_BulletBC_corrected * 0.95d);
                Target_Drop = drop_at_distance(Target_Distance, muzzle_velocity_m);
            } else {
                CC = (float) (m_BulletBC_corrected * 0.999d);
                RO = 1.0f;
                calc_SU(muzzle_velocity);
                Target_Drop = drop_at_distance_sub(Target_Distance);
            }
            if (ret_vel != 0.0d) {
                m_dPathCm = Float.valueOf(Round(Path_cm, 1));
                m_dPathMOA = Float.valueOf(Convert_cm_to_MOA(Path_cm, Target_Distance));
                m_dPathMOA = Float.valueOf(Round(m_dPathMOA.floatValue(), 2));
                m_dPathTD = Float.valueOf(Convert_cm_to_td(Path_cm, Target_Distance));
                m_dPathTD = Float.valueOf(Round(m_dPathTD.floatValue(), 2));
                m_PathClick = Float.valueOf(Round(m_dPathMOA.floatValue() / m_ScopeClickVert.floatValue(), 1));
                m_dWindCm = Float.valueOf(Round(Wind_cm, 1));
                m_dWindMOA = Float.valueOf(Convert_cm_to_MOA(Wind_cm, Target_Distance));
                m_dWindMOA = Float.valueOf(Round(m_dWindMOA.floatValue(), 2));
                m_dWindTD = Float.valueOf(Convert_cm_to_td(Wind_cm, Target_Distance));
                m_dWindTD = Float.valueOf(Round(m_dWindTD.floatValue(), 2));
                m_WindClick = Float.valueOf(Round(m_dWindMOA.floatValue() / m_ScopeClickGor.floatValue(), 1));
                energy = Round((float) (energy * 1.357d), 0);
                time_flight = Math.ceil(time_flight * 100.0d) / 100.0d;
                m_CurrentClickPrice = Convert_click_to_cm(m_ScopeClickVert.floatValue(), Target_Distance);
                m_CurrentClickPrice = Round((float) m_CurrentClickPrice, 2);
                ret_vel = Math.ceil(ret_vel * 10.0d) / 10.0d;
            } else {
                Path_cm = 0.0f;
                m_dPathCm = Float.valueOf(0.0f);
                m_dPathMOA = Float.valueOf(0.0f);
                m_dPathTD = Float.valueOf(0.0f);
                m_PathClick = Float.valueOf(0.0f);
                Wind_cm = 0.0f;
                m_dWindCm = Float.valueOf(0.0f);
                m_dWindMOA = Float.valueOf(0.0f);
                m_dWindTD = Float.valueOf(0.0f);
                m_WindClick = Float.valueOf(0.0f);
                time_flight = 0.0d;
                Target_Drop = 0.0f;
            }
        }
