    boolean SaveReticleToFile() {
        Bitmap bitmap = Bitmap.createBitmap(this._mildotdraw.getWidth(), this._mildotdraw.getHeight(), Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(bitmap);
        this._mildotdraw.draw(canvas);
        if (!"mounted".equals(Environment.getExternalStorageState())) {
            return false;
        }
        FileOutputStream fos = null;
        try {
            File sdcard = Environment.getExternalStorageDirectory();
            File dir = new File(sdcard, "/Strelok");
            dir.mkdir();
            String filename = Marks[this.cur_rifle.Reticle];
            this.jpg_filename = new File(dir, String.valueOf(filename) + ".jpg");
            FileOutputStream fos2 = new FileOutputStream(this.jpg_filename);
            fos = fos2;
        } catch (IOException ex) {
            ex.printStackTrace();
        }
        return bitmap.compress(Bitmap.CompressFormat.JPEG, 100, fos);
