    void DrawTriangle(Canvas canvas, int tipY, int tipX, int tailY, int tailX, int width_pix) {
        Paint paint = new Paint(C3_12x56);
        paint.setStrokeWidth(2.0f);
        paint.setColor(-16777216);
        paint.setStyle(Paint.Style.FILL);
        paint.setAntiAlias(true);
        Point point1_draw = new Point();
        Point point2_draw = new Point();
        Point point3_draw = new Point();
        point1_draw.x = tipX;
        point1_draw.y = tipY;
        if (tipY == tailY) {
            point2_draw.x = tailX;
            point2_draw.y = (width_pix / 2) + tailY;
            point3_draw.x = tailX;
            point3_draw.y = tailY - (width_pix / 2);
        } else {
            point2_draw.x = (width_pix / 2) + tailX;
            point2_draw.y = tailY;
            point3_draw.x = tailX - (width_pix / 2);
            point3_draw.y = tailY;
        }
        Path path = new Path();
        path.setFillType(Path.FillType.EVEN_ODD);
        path.moveTo(point1_draw.x, point1_draw.y);
        path.lineTo(point2_draw.x, point2_draw.y);
        path.lineTo(point3_draw.x, point3_draw.y);
        path.lineTo(point1_draw.x, point1_draw.y);
        path.close();
        canvas.drawPath(path, paint);
    }

