    protected void DrawVertDiamond(Canvas canvas, int centerY, int centerX, int high_pix) {
        int half_width = (int) ((high_pix / 2) * 0.7f);
        canvas.drawLine(centerX - half_width, centerY, centerX, centerY - (high_pix / 2), this.linePaint);
        canvas.drawLine(centerX, centerY - (high_pix / 2), centerX + half_width, centerY, this.linePaint);
        canvas.drawLine(centerX + half_width, centerY, centerX, (high_pix / 2) + centerY, this.linePaint);
        canvas.drawLine(centerX, (high_pix / 2) + centerY, centerX - half_width, centerY, this.linePaint);
    }

    protected void DrawHorDiamond(Canvas canvas, int centerY, int centerX, int length_pix) {
        int half_height = (int) ((length_pix / 2) * 0.7f);
        canvas.drawLine(centerX - (length_pix / 2), centerY, centerX, centerY - half_height, this.linePaint);
        canvas.drawLine(centerX, centerY - half_height, (length_pix / 2) + centerX, centerY, this.linePaint);
        canvas.drawLine((length_pix / 2) + centerX, centerY, centerX, centerY + half_height, this.linePaint);
        canvas.drawLine(centerX, centerY + half_height, centerX - (length_pix / 2), centerY, this.linePaint);
    }

