    protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
        int measuredWidth = measure(widthMeasureSpec);
        int measuredHeight = measure(heightMeasureSpec);
        int d = Math.min(measuredWidth, measuredHeight);
        setMeasuredDimension(d, d);
    }

package com.borisov.strelok;

    protected void SetNumbers() {
        int height = getMeasuredHeight();
        if (height == 0) {
            height = 100;
        }
        int width = getMeasuredWidth();
        if (width == 0) {
            width = 100;
        }
        int px = width / 2;
        int py = height / 2;
        this.middle_x = px;
        this.middle_y = py;
        if (height < width) {
            this.mil_length = height / (this.half_width * 2);
            this.moa = height / (this.half_width * 2);
        } else {
            this.mil_length = width / (this.half_width * 2);
            this.moa = width / (this.half_width * 2);
        }
        this.mil_length_base = this.mil_length;
        this.moa_base = this.moa;
        this.textPaint.setTextSize((this.mil_length * this.half_width) / 13.0f);
    }

package com.borisov.strelok;

    protected void showDist(Canvas canvas, float number_of_mils, float dist_from_vert) {
        int distance;
        float temp = gEngine.CalcDistanceFromDrop(number_of_mils);
        if (Settings.Metric_units_on.booleanValue()) {
            distance = (int) temp;
        } else {
            float dist_imp = Converter.M_TO_Y(temp).floatValue();
            distance = (int) dist_imp;
        }
        String resultString = String.valueOf(distance);
        int font_size = (int) this.textPaint.getTextSize();
        this.textPaint.setTextAlign(Paint.Align.LEFT);
        canvas.drawText(resultString, (int) (this.middle_x + dist_from_vert), (int) (this.middle_y + (this.mil_length * number_of_mils) + (font_size / 2.5d)), this.textPaint);
    }

