package com.borisov.strelok;

    protected void showWindMILS(Canvas canvas, float number_of_mils, float dist_from_vert) {
        float wind;
        String resultString;
        boolean show_digits = false;
        float temp = gEngine.CalcWindForMark(Math.abs(number_of_mils));
        if (Settings.Metric_units_on.booleanValue()) {
            if (temp < 10.0f) {
                wind = gEngine.Round(temp, C3_12x56);
                resultString = String.valueOf(wind);
            } else {
                wind = gEngine.Round(temp, C25_10x50);
                resultString = String.valueOf((int) wind);
            }
            if (wind < 20.0f) {
                show_digits = true;
            }
        } else {
            float wind_imp = Converter.MS_TO_MPH(temp).floatValue();
            wind = gEngine.Round(wind_imp, C25_10x50);
            resultString = String.valueOf((int) wind);
            if (wind_imp < 40.0f) {
                show_digits = true;
            }
        }
        if (wind == 0.0f) {
            show_digits = false;
        }
        this.windPaint.setTextAlign(Paint.Align.CENTER);
        this.windPaint.setTextSize((this.mil_length * this.half_width) / 13.0f);
        if (show_digits) {
            canvas.drawText(resultString, (int) (this.middle_x + (this.mil_length * number_of_mils)), (int) (this.middle_y - dist_from_vert), this.windPaint);
        }
    }

