    void ShowScopeInfo() {
        float zerodistance;
        float scopehight;
        Resources res = getResources();
        if (Settings.Metric_units_on.booleanValue()) {
            zerodistance = this.cur_rifle.ZeroDistance.floatValue();
            scopehight = this.cur_rifle.ScopeHight.floatValue();
        } else {
            zerodistance = Converter.M_TO_Y(this.cur_rifle.ZeroDistance.floatValue()).floatValue();
            scopehight = Converter.CM_TO_INCH(this.cur_rifle.ScopeHight.floatValue()).floatValue();
        }
        float temp_vert = this.cur_rifle.ScopeClickVert.floatValue();
        float temp_gor = this.cur_rifle.ScopeClickGor.floatValue();
        switch (this.cur_rifle.click_units) {
            case 0:
                temp_vert = gEngine.Round(temp_vert, 3);
                temp_gor = gEngine.Round(temp_gor, 3);
                break;
            case 1:
                temp_vert = gEngine.Round(Converter.MOA_TO_MIL(temp_vert).floatValue(), 4);
                temp_gor = gEngine.Round(Converter.MOA_TO_MIL(temp_gor).floatValue(), 4);
                break;
            case 2:
                temp_vert = gEngine.Round(Converter.MOA_TO_INCHES(temp_vert).floatValue(), 3);
                temp_gor = gEngine.Round(Converter.MOA_TO_INCHES(temp_gor).floatValue(), 3);
                break;
            case 3:
                temp_vert = gEngine.Round(Converter.MOA_TO_CM(temp_vert).floatValue(), 3);
                temp_gor = gEngine.Round(Converter.MOA_TO_CM(temp_gor).floatValue(), 3);
                break;
        }
        String[] scope_units = getResources().getStringArray(R.array.clicks_array);
        String click_units = scope_units[this.cur_rifle.click_units];
        String scope = res.getString(R.string.scope_label);
        String m_ScopeInfo = String.format("%s: %.0f/%.1f/%.2f/%.2f %s", scope, Float.valueOf(zerodistance), Float.valueOf(scopehight), Float.valueOf(temp_vert), Float.valueOf(temp_gor), click_units);
        this.btn_RifleScope.setText(String.valueOf(String.valueOf(String.valueOf(String.valueOf(m_ScopeInfo) + "\n") + res.getString(R.string.mark_label)) + ": ") + Mildot.Marks[this.cur_rifle.Reticle]);
    }

    void ShowRifleAtmState() {
        float altitude;
        float temperature;
        float pressure;
        Resources res = getResources();
        if (Settings.Metric_units_on.booleanValue()) {
            altitude = this.cur_rifle.Altitude.floatValue();
            temperature = this.cur_rifle.Temperature.floatValue();
        } else {
            altitude = Converter.M_TO_F(this.cur_rifle.Altitude.floatValue()).floatValue();
            temperature = Converter.C_TO_F(this.cur_rifle.Temperature.floatValue()).floatValue();
        }
        if (Settings.m_convert_to_hPa.booleanValue()) {
            pressure = Converter.MMHG_TO_HPA(this.cur_rifle.Pressure.floatValue()).floatValue();
        } else if (Settings.Metric_units_on.booleanValue()) {
            pressure = this.cur_rifle.Pressure.floatValue();
        } else {
            pressure = Converter.MMHG_TO_INHG(this.cur_rifle.Pressure.floatValue()).floatValue();
        }
        String m_RifleAtmInfo = res.getString(R.string.ZeroWeatherKey);
        this.btn_RifleAtm.setText(!this.cur_rifle.same_atm.booleanValue() ? String.valueOf(m_RifleAtmInfo) + String.format(": %.0f/%.0f/%.0f", Float.valueOf(altitude), Float.valueOf(temperature), Float.valueOf(pressure)) : String.valueOf(m_RifleAtmInfo) + res.getString(R.string.SameWeatherKey));
    }

    void ShowCartridgeInfo() {
        float bulletspeed;
        float bullettemperature;
        CartridgeObject cur_cartridge = this.cur_rifle.cartridges_array[this.cur_rifle.CurrentCartridge];
        if (Settings.Metric_units_on.booleanValue()) {
            bulletspeed = cur_cartridge.BulletSpeed.floatValue();
            bullettemperature = cur_cartridge.BulletTemperature.floatValue();
