            this.textRifleTemperature.setText(this.cur_rifle.Temperature.toString());
            this.label_rifle_altitude.setText(R.string.RifleAltitude_label);
            this.label_rifle_temp.setText(R.string.RifleTemperature_label);
        } else {
            Float altitude2 = Float.valueOf(gEngine.Round(Converter.M_TO_F(this.cur_rifle.Altitude.floatValue()).floatValue(), 0));
            this.textRifleAltitude.setText(altitude2.toString());
            this.textRifleTemperature.setText(Converter.C_TO_F(this.cur_rifle.Temperature.floatValue()).toString());
            this.label_rifle_altitude.setText(R.string.RifleAltitude_label_imp);
            this.label_rifle_temp.setText(R.string.RifleTemperature_label_imp);
        }
        if (Settings.m_convert_to_hPa.booleanValue()) {
            Float pressure = Converter.MMHG_TO_HPA(this.cur_rifle.Pressure.floatValue());
            this.textRiflePressure.setText(Float.valueOf(gEngine.Round(pressure.floatValue(), 0)).toString());
            this.label_rifle_pressure.setText(R.string.RiflePressure_label_hpa);
        } else if (Settings.Metric_units_on.booleanValue()) {
            Float pressure2 = this.cur_rifle.Pressure;
            this.textRiflePressure.setText(Float.valueOf(gEngine.Round(pressure2.floatValue(), 0)).toString());
            this.label_rifle_pressure.setText(R.string.RiflePressure_label);
        } else {
            Float pressure3 = Converter.MMHG_TO_INHG(this.cur_rifle.Pressure.floatValue());
            this.textRiflePressure.setText(Float.valueOf(gEngine.Round(pressure3.floatValue(), 2)).toString());
            this.label_rifle_pressure.setText(R.string.RiflePressure_label_imp);
        }
        this.same_atm_check.setChecked(!this.cur_rifle.same_atm.booleanValue());
        this.same_atm = this.cur_rifle.same_atm.booleanValue();
        this.textRifleAltitude.setEnabled(!this.same_atm);
        this.textRifleTemperature.setEnabled(!this.same_atm);
        this.textRiflePressure.setEnabled(this.same_atm ? false : true);
    }

    public void SaveFields() {
        String altitude = this.textRifleAltitude.getText().toString();
        String temperature = this.textRifleTemperature.getText().toString();
        String pressure = this.textRiflePressure.getText().toString();
        if (Settings.Metric_units_on.booleanValue()) {
            if (altitude.length() != 0) {
                this.cur_rifle.Altitude = Float.valueOf(Float.parseFloat(altitude));
            }
            if (temperature.length() != 0) {
                this.cur_rifle.Temperature = Float.valueOf(Float.parseFloat(temperature));
            }
        } else {
            if (altitude.length() != 0) {
                float buffer = Float.parseFloat(altitude);
                this.cur_rifle.Altitude = Converter.F_TO_M(buffer);
            }
            if (temperature.length() != 0) {
                float buffer2 = Float.parseFloat(temperature);
                this.cur_rifle.Temperature = Converter.F_TO_C(buffer2);
            }
        }
        this.cur_rifle.same_atm = Boolean.valueOf(this.same_atm);
        if (Settings.m_convert_to_hPa.booleanValue()) {
            if (pressure.length() != 0) {
                this.cur_rifle.Pressure = Converter.HPA_TO_MMHG(Float.parseFloat(pressure));
                return;
            }
            return;
        }
        if (Settings.Metric_units_on.booleanValue()) {
            if (pressure.length() != 0) {
                this.cur_rifle.Pressure = Float.valueOf(Float.parseFloat(pressure));
                return;
            }
            return;
        }
        if (pressure.length() != 0) {
            this.cur_rifle.Pressure = Converter.INHG_TO_MMHG(Float.parseFloat(pressure));
        }
    }

    @Override // android.view.View.OnClickListener
    public void onClick(View src) {
        switch (src.getId()) {
            case R.id.ButtonOK /* 2131165198 */:
                SaveFields();
                finish();
                break;
            case R.id.ButtonCancel /* 2131165199 */:
                finish();
                break;
            case R.id.same_atm_switch /* 2131165249 */:
                this.same_atm = !this.same_atm_check.isChecked();
                this.textRifleAltitude.setEnabled(!this.same_atm);
                this.textRifleTemperature.setEnabled(!this.same_atm);
                this.textRiflePressure.setEnabled(this.same_atm ? false : true);
                break;
        }
    }

    @Override // android.app.Activity, android.view.KeyEvent.Callback
    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (keyCode != 4 || event.getRepeatCount() != 0) {
            return super.onKeyDown(keyCode, event);
        }
        SaveFields();
        finish();
        return true;
    }

    @Override // android.app.Activity
    protected void onPause() {
        SaveFields();
        super.onPause();
    }

    @Override // android.app.Activity
    protected void onResume() {
        super.onResume();
        ShowFields();
    }
}

