    public static void Init(Context context) {
        r_array = new RifleObject[]{new RifleObject(), new RifleObject(), new RifleObject(), new RifleObject(), new RifleObject(), new RifleObject(), new RifleObject()};
        if (!ReadRiflesArrayFromFile()) {
            ReadRiflesFromPreferences(context);
        }
    }

package com.borisov.strelok;

    static boolean ReadRiflesArrayFromFile() {
        if (!"mounted".equals(Environment.getExternalStorageState())) {
            return false;
        }
        try {
            File sdard = Environment.getExternalStorageDirectory();
            File filename = new File(sdard, "/Strelok/rifles.dat");
            FileInputStream fis = new FileInputStream(filename);
            try {
                ObjectInputStream in = new ObjectInputStream(fis);
                try {
                    r_array = (RifleObject[]) in.readObject();
                    in.close();
                    return true;
                } catch (IOException e) {
                    ex = e;
                    ex.printStackTrace();
                    return false;
                } catch (ClassNotFoundException e2) {
                    ex = e2;
                    ex.printStackTrace();
                    return false;
                }
            } catch (IOException e3) {
                ex = e3;
            } catch (ClassNotFoundException e4) {
                ex = e4;
            }
        } catch (IOException e5) {
            ex = e5;
        } catch (ClassNotFoundException e6) {
            ex = e6;
        }
    }

