    public void ReadClicksValue() {
        float temp_vert;
        float temp_gor;
        String vert = this.textScopeClickVert.getText().toString();
        String gor = this.textScopeClickGor.getText().toString();
        if (vert.length() != 0) {
            temp_vert = Float.parseFloat(vert);
        } else {
            temp_vert = 0.25f;
        }
        if (gor.length() != 0) {
            temp_gor = Float.parseFloat(gor);
        } else {
            temp_gor = 0.25f;
        }
        switch (this.cur_rifle.click_units) {
            case 1:
                temp_vert = Converter.MIL_TO_MOA(temp_vert).floatValue();
                temp_gor = Converter.MIL_TO_MOA(temp_gor).floatValue();
                break;
            case 2:
                temp_vert = Converter.INCHES_TO_MOA(temp_vert).floatValue();
                temp_gor = Converter.INCHES_TO_MOA(temp_gor).floatValue();
                break;
            case 3:
                temp_vert = Converter.CM_TO_MOA(temp_vert).floatValue();
