            this.m_GeometrAngle = angle_from_X_axle((int) this.middle_x, (int) this.middle_y, (int) event.getX(), (int) event.getY());
            this.cur_x = (int) event.getX();
            if (this.cur_x < this.middle_x) {
                this.cur_x = (int) this.middle_x;
            }
            this.cur_y = (int) event.getY();
            invalidate();
            return true;
        }
        event.getAction();
        return true;
    }

    float angle_from_X_axle(int first_point_x, int first_point_y, int last_point_x, int last_point_y) {
        float alpha;
        float delta_x = last_point_x - first_point_x;
        float delta_y = last_point_y - first_point_y;
        if (delta_x == 0.0f) {
            if (delta_y > 0.0f) {
                alpha = -90.0f;
            } else {
                alpha = 90.0f;
            }
        } else if (delta_x > 0.0f) {
            alpha = (float) (((-Math.atan(delta_y / delta_x)) * 180.0d) / 3.141592653589793d);
        } else if (delta_y > 0.0f) {
            alpha = (float) ((((-3.141592653589793d) - Math.atan(delta_y / delta_x)) * 180.0d) / 3.141592653589793d);
        } else {
            alpha = (float) (((3.141592653589793d - Math.atan(delta_y / delta_x)) * 180.0d) / 3.141592653589793d);
        }
        if (alpha > 90.0f) {
            alpha = 89.0f;
        }
        if (alpha < -90.0f) {
            return -89.0f;
        }
        return alpha;
    }

    void SaveAngleToEngine() {
        gEngine.m_SlopeAngle = Float.valueOf(gEngine.Round(this.m_GeometrAngle, 0));
    }

    protected void SetArrowCoords() {
        float vector_len;
        int height = getMeasuredHeight();
        int width = getMeasuredWidth();
        if (width != 0 && height != 0) {
            if (Math.abs(this.m_GeometrAngle) < 30.0f) {
                vector_len = (float) ((width * 0.9d) / Math.cos((this.m_GeometrAngle * 3.141592653589793d) / 180.0d));
            } else {
                vector_len = (float) (((height * 0.9d) / 2.0d) / Math.sin((Math.abs(this.m_GeometrAngle) * 3.141592653589793d) / 180.0d));
            }
            coords_from_angle(vector_len, this.m_GeometrAngle);
            int x_delta = this.temp_x;
            int y_delta = this.temp_y;
            this.cur_x = (int) (this.middle_x + x_delta);
            this.cur_y = (int) (this.middle_y - y_delta);
            return;
        }
        this.cur_x = 0;
        this.cur_y = 0;
    }

    protected void SetAngle() {
        this.m_GeometrAngle = gEngine.m_SlopeAngle.floatValue();
        invalidate();
    }

    protected void coords_from_angle(float len, float angle) {
        if (angle >= 0.0f) {
            this.temp_x = (int) (len * Math.cos((angle * 3.141592653589793d) / 180.0d));
            this.temp_y = (int) (len * Math.sin((angle * 3.141592653589793d) / 180.0d));
        } else {
            float angle2 = -angle;
            this.temp_x = (int) (len * Math.cos((angle2 * 3.141592653589793d) / 180.0d));
            this.temp_y = -((int) (len * Math.sin((angle2 * 3.141592653589793d) / 180.0d)));
        }
    }

