            this.textDistance.setText(distance2.toString());
            Float wind2 = Float.valueOf(gEngine.Round(Converter.MS_TO_MPH(gEngine.m_WindSpeed.floatValue()).floatValue(), 1));
            this.textWind.setText(wind2.toString());
            this.btn_WindDirection.setText(gEngine.m_nDirection.toString());
            this.label_distance.setText(R.string.distance_label_imp);
