package com.borisov.strelok;

    boolean SaveTableToCSVFile() {
        if (!"mounted".equals(Environment.getExternalStorageState())) {
            return false;
        }
        try {
            File sdcard = Environment.getExternalStorageDirectory();
            File dir = new File(sdcard, "/Strelok");
            dir.mkdir();
            this.csv_filename = new File(dir, "table.csv");
            FileOutputStream fos = new FileOutputStream(this.csv_filename);
            try {
                fos.write(239);
                fos.write(187);
                fos.write(191);
                OutputStreamWriter stream = new OutputStreamWriter(fos, "utf8");
                try {
                    stream.write(this.csv_table);
                    stream.close();
                    return true;
                } catch (IOException e) {
                    ex = e;
                    ex.printStackTrace();
                    return false;
                }
            } catch (IOException e2) {
                ex = e2;
            }
        } catch (IOException e3) {
            ex = e3;
        }
    }

