            case R.id.send_email /* 2131165291 */:
                Intent emailIntent = new Intent("android.intent.action.SEND_MULTIPLE");
                emailIntent.setType("plain/text");
                emailIntent.putExtra("android.intent.extra.SUBJECT", "Strelok ballistic table");
                ArrayList<Uri> uris = new ArrayList<>();
                if (SaveCSV().booleanValue()) {
                    Uri u = Uri.fromFile(this.csv_filename);
                    uris.add(u);
                }
                if (SaveHTM().booleanValue()) {
                    Uri u2 = Uri.fromFile(this.htm_filename);
                    uris.add(u2);
                }
                if (uris.isEmpty()) {
                    emailIntent.putExtra("android.intent.extra.TEXT", "Strelok ballistic table\n");
                    emailIntent.putExtra("android.intent.extra.STREAM", Uri.fromFile(this.htm_filename));
                } else {
                    emailIntent.putExtra("android.intent.extra.TEXT", "Strelok ballistic table\n\n");
                    emailIntent.putParcelableArrayListExtra("android.intent.extra.STREAM", uris);
                }
                startActivity(Intent.createChooser(emailIntent, "Email:"));
                return true;
            default:
                return super.onOptionsItemSelected(item);
        }
    }

    boolean SaveTableToHTMFile() {
        if (!"mounted".equals(Environment.getExternalStorageState())) {
            return false;
        }
        try {
            File sdcard = Environment.getExternalStorageDirectory();
            File dir = new File(sdcard, "/Strelok");
            dir.mkdir();
            this.htm_filename = new File(dir, "table.htm");
            FileOutputStream fos = new FileOutputStream(this.htm_filename);
            try {
                OutputStreamWriter stream = new OutputStreamWriter(fos, "utf8");
                try {
                    stream.write(this.html_string);
                    stream.close();
                    return true;
                } catch (IOException e) {
                    ex = e;
                    ex.printStackTrace();
                    return false;
                }
            } catch (IOException e2) {
                ex = e2;
            }
        } catch (IOException e3) {
            ex = e3;
        }
    }

    boolean SaveTableToCSVFile() {
        if (!"mounted".equals(Environment.getExternalStorageState())) {
            return false;
